#include <stdio.h>

#define COLS 3

void show(size_t rows, int grid[][COLS]) {         /* the inner size is required. */
    for (size_t r = 0; r < rows; r++) {
        for (size_t c = 0; c < COLS; c++) {
            printf("%d ", grid[r][c]);             /* row, then column. */
        }
        putchar('\n');
    }
}

int main(void) {
    int seats[2][COLS] = {
        {1, 0, 1},       /* row 0. */
        {0, 0, 1},       /* row 1. */
    };
    show(2, seats);
    return 0;
}
```

